/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { Router, NavigationEnd } from '@angular/router';
import { BehaviorSubject, Subject } from 'rxjs';
import { trace } from '@opentelemetry/api';
import { InstrumentationService, tabSessionId } from './instrumentation.service';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { Logger } from './logger.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { tenantSpanProcessor } from './otel-bootstrap';

function loggerSpy() {
  return jasmine.createSpyObj<Logger>('Logger', ['debug', 'info', 'warn', 'error', 'attachRemote', 'captureConsole']);
}

function configOf(telemetry$: Subject<any>) {
  return { value$: () => telemetry$.asObservable() };
}

function appStateOf(tenant$ = new BehaviorSubject<string>('main')) {
  return { tenant: tenant$.asObservable() };
}

describe('InstrumentationService — getTracer / startSpan', () => {
  let service: InstrumentationService;
  let routerEvents$: Subject<any>;

  beforeEach(() => {
    routerEvents$ = new Subject();
    TestBed.configureTestingModule({
      providers: [
        InstrumentationService,
        { provide: Router, useValue: { events: routerEvents$.asObservable() } },
        { provide: RuntimeConfigService, useValue: configOf(new Subject()) },
        { provide: Logger, useValue: loggerSpy() },
        { provide: AppStateService, useValue: appStateOf() },
      ],
    });
    service = TestBed.inject(InstrumentationService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('getTracer returns a tracer with a startSpan method', () => {
    const tracer = service.getTracer('my-service');
    expect(tracer).toBeDefined();
    expect(typeof tracer.startSpan).toBe('function');
  });

  it('getTracer returns the same instance on repeated calls with the same name', () => {
    const first = service.getTracer('cached-service');
    const second = service.getTracer('cached-service');
    expect(first).toBe(second);
  });

  it('getTracer returns different instances for different names', () => {
    const first = service.getTracer('service-a');
    const second = service.getTracer('service-b');
    expect(first).not.toBe(second);
  });

  it('getTracer without arguments defaults to "default"', () => {
    const noArg = service.getTracer();
    const explicit = service.getTracer('default');
    expect(noArg).toBe(explicit);
  });

  it('startSpan returns a span with an end method', () => {
    const span = service.startSpan('test-span');
    expect(span).toBeDefined();
    expect(typeof span.end).toBe('function');
    span.end();
  });

  it('startSpan uses a different tracer name than default when specified', () => {
    const spanA = service.startSpan('span', 'tracer-a');
    const spanB = service.startSpan('span', 'tracer-b');
    // Both return valid spans; different tracer names use separate cached tracers
    expect(spanA).toBeDefined();
    expect(spanB).toBeDefined();
    spanA.end();
    spanB.end();
  });

  it('startSpan passes custom attributes to the tracer', () => {
    // Real OTel no-op tracer accepts attributes — just verify it does not throw
    expect(() => service.startSpan('attributed-span', 'default', { userId: '42', requestId: 'abc' })).not.toThrow();
  });
});

describe('InstrumentationService — activate early-return', () => {
  let service: InstrumentationService;
  let routerEvents$: Subject<any>;
  let telemetryConf$: Subject<any>;
  let logger: jasmine.SpyObj<Logger>;

  beforeEach(() => {
    routerEvents$ = new Subject();
    telemetryConf$ = new Subject();
    logger = loggerSpy();
    TestBed.configureTestingModule({
      providers: [
        InstrumentationService,
        { provide: Router, useValue: { events: routerEvents$.asObservable() } },
        { provide: RuntimeConfigService, useValue: configOf(telemetryConf$) },
        { provide: Logger, useValue: logger },
        { provide: AppStateService, useValue: appStateOf() },
      ],
    });
    service = TestBed.inject(InstrumentationService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('logs and returns early when telemetry name is not set', async () => {
    const activation = service.activate();
    telemetryConf$.next({});
    await activation;
    expect(logger.debug).toHaveBeenCalledWith('Telemetry disabled: add telemetry.name to the config');
    expect(logger.attachRemote).not.toHaveBeenCalled();
  });

  it('logs and returns early when telemetry name is null', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: null });
    await activation;
    expect(logger.debug).toHaveBeenCalledWith('Telemetry disabled: add telemetry.name to the config');
  });
});

describe('InstrumentationService — activate with name set', () => {
  let service: InstrumentationService;
  let routerEvents$: Subject<any>;
  let telemetryConf$: Subject<any>;
  let logger: jasmine.SpyObj<Logger>;
  let mockSpan: any;
  let mockTracer: any;

  beforeEach(() => {
    routerEvents$ = new Subject();
    telemetryConf$ = new Subject();
    logger = loggerSpy();
    mockSpan = { end: jasmine.createSpy('end'), setAttribute: jasmine.createSpy('setAttribute') };
    mockTracer = { startSpan: jasmine.createSpy('startSpan').and.returnValue(mockSpan) };
    spyOn(trace, 'getTracer').and.returnValue(mockTracer as any);

    TestBed.configureTestingModule({
      providers: [
        InstrumentationService,
        { provide: Router, useValue: { events: routerEvents$.asObservable() } },
        { provide: RuntimeConfigService, useValue: configOf(telemetryConf$) },
        { provide: Logger, useValue: logger },
        { provide: AppStateService, useValue: appStateOf() },
      ],
    });
    service = TestBed.inject(InstrumentationService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('does not log the early-return message when telemetry name is set', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await activation;
    expect(logger.debug).not.toHaveBeenCalled();
  });

  it('creates and ends a span for NavigationEnd events', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await activation;

    routerEvents$.next(new NavigationEnd(1, '/home', '/home'));

    expect(mockTracer.startSpan).toHaveBeenCalledWith('navigation', {
      attributes: { 'route.path': '/home' },
    });
    expect(mockSpan.end).toHaveBeenCalled();
  });

  it('records the urlAfterRedirects in the span attribute', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await activation;

    routerEvents$.next(new NavigationEnd(2, '/old', '/redirected-path'));

    expect(mockTracer.startSpan).toHaveBeenCalledWith('navigation', {
      attributes: { 'route.path': '/redirected-path' },
    });
  });

  it('does not create spans for non-NavigationEnd router events', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await activation;

    routerEvents$.next({ type: 'NavigationStart' });
    routerEvents$.next({ type: 'RoutesRecognized' });

    expect(mockSpan.end).not.toHaveBeenCalled();
  });

  it('is idempotent: second activate call does not re-subscribe', async () => {
    const first = service.activate();
    const second = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await Promise.all([first, second]);

    routerEvents$.next(new NavigationEnd(3, '/a', '/a'));
    expect(mockTracer.startSpan).toHaveBeenCalledTimes(1);
  });
});

describe('InstrumentationService — logger sink', () => {
  let service: InstrumentationService;
  let telemetryConf$: Subject<any>;
  let logger: jasmine.SpyObj<Logger>;
  let originalConsoleLog: typeof console.log;

  beforeEach(() => {
    originalConsoleLog = console.log;
    telemetryConf$ = new Subject();
    logger = loggerSpy();
    TestBed.configureTestingModule({
      providers: [
        InstrumentationService,
        { provide: Router, useValue: { events: new Subject<any>().asObservable() } },
        { provide: RuntimeConfigService, useValue: configOf(telemetryConf$) },
        { provide: Logger, useValue: logger },
        { provide: AppStateService, useValue: appStateOf() },
      ],
    });
    service = TestBed.inject(InstrumentationService);
  });

  afterEach(() => TestBed.resetTestingModule());

  const exporter = { tracer: false, logger: { url: 'http://localhost/v1/logs' } };

  it('attaches the OTLP sink to Logger without capturing console by default', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter });
    await activation;

    expect(logger.attachRemote).toHaveBeenCalledWith(jasmine.any(Function));
    expect(logger.captureConsole).not.toHaveBeenCalled();
    expect(console.log).toBe(originalConsoleLog);
  });

  it('captures console only with telemetry.logger.capture-console: true', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter, logger: { 'capture-console': true } });
    await activation;

    expect(logger.captureConsole).toHaveBeenCalled();
  });

  it('does not attach a sink when the logger exporter is not configured', async () => {
    const activation = service.activate();
    telemetryConf$.next({ name: 'test-service', exporter: { tracer: false, logger: false } });
    await activation;

    expect(logger.attachRemote).not.toHaveBeenCalled();
  });
});

describe('InstrumentationService — tab session id', () => {
  beforeEach(() => sessionStorage.removeItem('telemetry-session-id'));

  it('generates a random id once and reuses it within the tab', () => {
    const first = tabSessionId();
    expect(first).toMatch(/^[0-9a-f-]{32,36}$/);
    expect(tabSessionId()).toBe(first);
  });
});

describe('tenantSpanProcessor', () => {
  it('sets app.tenant with the tenant active when the span starts', () => {
    let tenant: string | undefined = 'acme';
    const processor = tenantSpanProcessor(() => tenant);
    const span = jasmine.createSpyObj('Span', ['setAttribute']);

    processor.onStart(span, {} as any);
    tenant = 'globex';
    processor.onStart(span, {} as any);

    expect(span.setAttribute.calls.allArgs()).toEqual([
      ['app.tenant', 'acme'],
      ['app.tenant', 'globex'],
    ]);
  });

  it('does not set the attribute without tenant', () => {
    const processor = tenantSpanProcessor(() => undefined);
    const span = jasmine.createSpyObj('Span', ['setAttribute']);
    processor.onStart(span, {} as any);
    expect(span.setAttribute).not.toHaveBeenCalled();
  });
});
